from typing import List, Any

def monotonic(l: list):
    """Return True if list elements are monotonically increasing or decreasing (non-strict).
    >>> monotonic([1, 2, 4, 20])
    True
    >>> monotonic([1, 20, 4, 10])
    False
    >>> monotonic([4, 1, 0, -10])
    True
    """
    n = len(l)
    if n <= 2:
        return True

    # Find the first non-equal adjacent pair to determine trend
    direction = 0  # 0 unknown, 1 non-decreasing, -1 non-increasing
    for i in range(1, n):
        if l[i] != l[i - 1]:
            direction = 1 if l[i] > l[i - 1] else -1
            break

    # All elements equal or only equal pairs encountered
    if direction == 0:
        return True

    if direction == 1:
        # non-decreasing: each next >= prev
        for i in range(1, n):
            if l[i] < l[i - 1]:
                return False
    else:
        # non-increasing: each next <= prev
        for i in range(1, n):
            if l[i] > l[i - 1]:
                return False

    return True
